int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;
    int N = n * m;
    vector<vector<int>> a(n, vector<int>(m));
    int maxId = 0;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < m; ++j) {
            cin >> a[i][j];
            maxId = max(maxId, a[i][j]);
        }

    // positions of each pair id: exactly two positions
    vector<pair<int,int>> pos1(maxId+1, {-1,-1}), pos2(maxId+1, {-1,-1});
    vector<int> cnt(maxId+1,0);
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < m; ++j) {
            int id = a[i][j];
            if (cnt[id] == 0) pos1[id] = {i,j};
            else pos2[id] = {i,j};
            cnt[id]++;
        }

    int blackCnt = (N + 1) / 2;
    int whiteCnt = N / 2;

    // adjacency matrix: cost from black index to white index
    const int INF = 1e9;
    vector<vector<int>> cost(blackCnt, vector<int>(whiteCnt, INF));

    // mapping from (i,j) to index in black/white
    auto isBlack = [&](int i, int j) {
        return ((i + j) & 1) == 0;
    };
    auto idxBlack = [&](int i, int j) {
        return (i * m + j) / 2;
    };
    auto idxWhite = [&](int i, int j) {
        return (i * m + j - 1) / 2;
    };

    // For each pair, consider all possible adjacent final placements
    // and update minimal cost for that black-white edge.
    for (int id = 1; id <= maxId; ++id) {
        auto [x1, y1] = pos1[id];
        auto [x2, y2] = pos2[id];

        // enumerate all adjacent cell pairs
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                const int di[4] = {1,-1,0,0};
                const int dj[4] = {0,0,1,-1};
                for (int d = 0; d < 4; ++d) {
                    int ni = i + di[d], nj = j + dj[d];
                    if (ni < 0 || ni >= n || nj < 0 || nj >= m) continue;
                    // we only consider each unordered pair once: ensure (i,j) < (ni,nj) in linear index
                    int idx1 = i * m + j;
                    int idx2 = ni * m + nj;
                    if (idx2 < idx1) continue;

                    // determine black/white positions
                    int bi, bj, wi, wj;
                    if (isBlack(i,j)) {
                        bi = i; bj = j; wi = ni; wj = nj;
                    } else {
                        bi = ni; bj = nj; wi = i; wj = j;
                    }
                    int bIdx = idxBlack(bi, bj);
                    int wIdx = idxWhite(wi, wj);

                    // cost: number of shoes of this pair moved
                    int c = 0;
                    if (!(x1 == bi && y1 == bj) && !(x2 == bi && y2 == bj)) c++;
                    if (!(x1 == wi && y1 == wj) && !(x2 == wi && y2 == wj)) c++;
                    cost[bIdx][wIdx] = min(cost[bIdx][wIdx], c);
                }
            }
        }
    }

    // Hungarian algorithm for rectangular matrix (blackCnt x whiteCnt)
    int nL = blackCnt, nR = whiteCnt;
    int nDim = max(nL, nR);
    vector<vector<int>> cHung(nDim, vector<int>(nDim, INF));
    for (int i = 0; i < nL; ++i)
        for (int j = 0; j < nR; ++j)
            cHung[i][j] = cost[i][j];

    vector<int> u(nDim+1), v(nDim+1), p(nDim+1), way(nDim+1);
    for (int i = 1; i <= nDim; ++i) {
        p[0] = i;
        int j0 = 0;
        vector<int> minv(nDim+1, INF);
        vector<char> used(nDim+1, false);
        do {
            used[j0] = true;
            int i0 = p[j0], delta = INF, j1 = 0;
            for (int j = 1; j <= nDim; ++j)
                if (!used[j]) {
                    int cur = cHung[i0-1][j-1] - u[i0] - v[j];
                    if (cur < minv[j]) {
                        minv[j] = cur;
                        way[j] = j0;
                    }
                    if (minv[j] < delta) {
                        delta = minv[j];
                        j1 = j;
                    }
                }
            for (int j = 0; j <= nDim; ++j) {
                if (used[j]) {
                    u[p[j]] += delta;
                    v[j] -= delta;
                } else {
                    minv[j] -= delta;
                }
            }
            j0 = j1;
        } while (p[j0] != 0);
        do {
            int j1 = way[j0];
            p[j0] = p[j1];
            j0 = j1;
        } while (j0);
    }

    long long ans = 0;
    for (int j = 1; j <= nDim; ++j) {
        int i = p[j];
        if (i >= 1 && i <= nL && j >= 1 && j <= nR) {
            if (cHung[i-1][j-1] < INF) ans += cHung[i-1][j-1];
        }
    }

    cout << ans << "\n";
    return 0;
}

