    int N = n * m;
    vector<vector<int>> a(n, vector<int>(m));
    int maxId = 0;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < m; ++j) {
            cin >> a[i][j];
            maxId = max(maxId, a[i][j]);
        }

    // positions of each pair id (1..maxId)
    vector<pair<int,int>> pos1(maxId+1, {-1,-1}), pos2(maxId+1, {-1,-1});
    vector<int> cnt(maxId+1,0);
    for(int i=0;i<n;i++){
        for(int j=0;j<m;j++){
            int id=a[i][j];
            if(cnt[id]==0) pos1[id]={i,j};
            else pos2[id]={i,j};
            cnt[id]++;
        }
    }

    // bipartite graph: left = black cells, right = white cells
    // color by (i+j)%2
    vector<vector<int>> adj(N); // edges from left index to right index
    auto idx = [m](int i,int j){ return i*m + j; };

    const int INF = 1e9;
    int totalPairs = maxId;

    for(int id=1; id<=maxId; ++id){
        auto [x1,y1]=pos1[id];
        auto [x2,y2]=pos2[id];
        int d = abs(x1-x2)+abs(y1-y2);
        if(d==1){
            // already adjacent, no constraint
            continue;
        }
        // we need to choose an adjacent pair of cells (u,v) for this id
        // u and v must be neighbors; we add edge between u and v
        // but we only add edges from black to white
        vector<pair<int,int>> cells;
        cells.push_back({x1,y1});
        cells.push_back({x2,y2});
        for(auto [x,y]:cells){
            const int dx[4]={1,-1,0,0};
            const int dy[4]={0,0,1,-1};
            for(int k=0;k<4;k++){
                int nx=x+dx[k], ny=y+dy[k];
                if(nx<0||nx>=n||ny<0||ny>=m) continue;
                int u = idx(x,y);
                int v = idx(nx,ny);
                if(((x+y)&1)==0){
                    adj[u].push_back(v);
                }else{
                    adj[v].push_back(u);
                }
            }
        }
    }

    // Hopcroft-Karp
    vector<int> pairU(N, -1), pairV(N, -1), dist(N);
    auto bfs = [&]() {
        queue<int> q;
        for(int u=0;u<N;u++){
            if(((u/m + u%m)&1)==0){ // left side
                if(pairU[u]==-1){
                    dist[u]=0;
                    q.push(u);
                }else dist[u]=INF;
            }
        }
        int dINF = INF;
        while(!q.empty()){
            int u=q.front();q.pop();
            if(dist[u]<dINF){
                for(int v:adj[u]){
                    int pu = pairV[v];
                    if(pu==-1){
                        dINF = dist[u]+1;
                    }else if(dist[pu]==INF){
                        dist[pu]=dist[u]+1;
                        q.push(pu);
                    }
                }
            }
        }
        return dINF!=INF;
    };

    function<bool(int)> dfs = [&](int u){
        for(int v:adj[u]){
            int pu = pairV[v];
            if(pu==-1 || (dist[pu]==dist[u]+1 && dfs(pu))){
                pairU[u]=v;
                pairV[v]=u;
                return true;
            }
        }
        dist[u]=INF;
        return false;
    };

    int matching = 0;
    while(bfs()){
        for(int u=0;u<N;u++){
            if(((u/m + u%m)&1)==0 && pairU[u]==-1){
                if(dfs(u)) matching++;
            }
        }
    }

    // Each matched edge corresponds to one pair placed correctly (2 shoes fixed)
    // Total shoes = N, shoes moved = N - 2*matching
    int result = N - 2*matching;
    cout << result << '\n';
    return 0;
}

