using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;
    int N = n * m;
    vector<vector<int>> a(n, vector<int>(m));
    int maxId = 0;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < m; ++j) {
            cin >> a[i][j];
            maxId = max(maxId, a[i][j]);
        }

    // positions of each pair id (1..maxId), each occurs exactly twice
    vector<pair<int,int>> pos1(maxId+1, {-1,-1}), pos2(maxId+1, {-1,-1});
    vector<int> cnt(maxId+1,0);
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < m; ++j) {
            int id = a[i][j];
            if (cnt[id] == 0) pos1[id] = {i,j};
            else pos2[id] = {i,j};
            cnt[id]++;
        }

    // build bipartite graph: left = black cells, right = white cells
    // color by (i+j)%2
    int blacks = 0, whites = 0;
    vector<vector<int>> idL(n, vector<int>(m,-1)), idR(n, vector<int>(m,-1));
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < m; ++j) {
            if ((i + j) % 2 == 0) idL[i][j] = blacks++;
            else idR[i][j] = whites++;
        }

    int L = blacks, R = whites;
    vector<vector<int>> adj(L);

    // For each pair, add edges between its two cells if they are opposite colors
    for (int id = 1; id <= maxId; ++id) {
        auto [x1,y1] = pos1[id];
        auto [x2,y2] = pos2[id];
        if ((x1 + y1) % 2 == (x2 + y2) % 2) {
            // impossible to be adjacent in final grid, but problem guarantees solvable
            continue;
        }
        int u, v;
        if ((x1 + y1) % 2 == 0) {
            u = idL[x1][y1];
            v = idR[x2][y2];
        } else {
            u = idL[x2][y2];
            v = idR[x1][y1];
        }
        adj[u].push_back(v);
    }

    // maximum bipartite matching (Hopcroft-Karp)
    const int INF = 1e9;
    vector<int> pairU(L, -1), pairV(R, -1), dist(L);

    function<bool()> bfs = [&]() {
        queue<int> q;
        for (int u = 0; u < L; ++u) {
            if (pairU[u] == -1) {
                dist[u] = 0;
                q.push(u);
            } else dist[u] = INF;
        }
        int dINF = INF;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            if (dist[u] < dINF) {
                for (int v : adj[u]) {
                    int pu = pairV[v];
                    if (pu == -1) {
                        dINF = dist[u] + 1;
                    } else if (dist[pu] == INF) {
                        dist[pu] = dist[u] + 1;
                        q.push(pu);
                    }
                }
            }
        }
        return dINF != INF;
    };

    function<bool(int)> dfs = [&](int u) {
        for (int v : adj[u]) {
            int pu = pairV[v];
            if (pu == -1 || (dist[pu] == dist[u] + 1 && dfs(pu))) {
                pairU[u] = v;
                pairV[v] = u;
                return true;
            }
        }
        dist[u] = INF;
        return false;
    };

    int matching = 0;
    while (bfs()) {
        for (int u = 0; u < L; ++u)
            if (pairU[u] == -1 && dfs(u))
                ++matching;
    }

    // number of pairs = N/2
    int pairs = N / 2;
    int maxAdjPairs = matching;
    int minMovedShoes = N - 2 * maxAdjPairs;
    cout << minMovedShoes << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

/*
We need minimum number of shoes moved so that each pair of equal numbers occupies two
adjacent cells (Manhattan distance 1). Each shoe moved counts 1; we can move any shoe
anywhere (effectively we choose final positions). We only care about which shoes stay.

Equivalent: choose a set of shoes to remain in place such that:
- For every pair id, either 0 or 2 of its shoes remain.
- If 2 remain, they must be adjacent cells.
Maximize number of shoes that remain; answer = total_shoes - max_remain.

Observation: Grid is bipartite by (i+j)%2. Any adjacent pair is between opposite colors.
Each pair id has two positions; they are either on opposite colors (good) or same color.
If same color, they can never be adjacent in final neat arrangement, so at most one of
them can stay; but since we need 0 or 2 per pair, they must both move -> contribute 2
moves always. So we can ignore such pairs for optimization (they add constant).

For pairs whose two cells are on opposite colors, they are candidate edges between the
two bipartite partitions. We want to select some of these edges so that:
- No cell is used by more than one selected edge (matching).
- For each selected edge (pair), both shoes stay (2).
This is exactly a maximum matching on a bipartite graph where:
- Left nodes: cells with color 0.
- Right nodes: cells with color 1.
- Edge between two cells if they belong to same pair id and are opposite colors.

Maximum matching size = number of pairs that can stay fully. Each contributes 2 shoes.
Shoes from pairs not in matching must move (2 each). Pairs with same-color positions
also contribute 2 moves each (constant). So:
answer = total_shoes - 2 * max_matching = n*m - 2*max_matching.

We just need to build bipartite graph over cells and run Hopcroft-Karp.
*/

struct HopcroftKarp {
    int nL, nR;
    vector<vector<int>> adj;
    vector<int> dist, pairU, pairV;

    HopcroftKarp(int nL, int nR) : nL(nL), nR(nR) {
        adj.assign(nL, {});
        pairU.assign(nL, -1);
        pairV.assign(nR, -1);
        dist.resize(nL);
    }

    void addEdge(int u, int v) {
        adj[u].push_back(v);
    }

    bool bfs() {
        queue<int> q;
        for (int u = 0; u < nL; ++u) {
            if (pairU[u] == -1) {
                dist[u] = 0;
                q.push(u);
            } else {
                dist[u] = -1;
            }
        }
        bool found = false;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int v : adj[u]) {
                int pu = pairV[v];
                if (pu != -1 && dist[pu] == -1) {
                    dist[pu] = dist[u] + 1;
                    q.push(pu);
                }
                if (pu == -1) found = true;
            }
        }
        return found;
    }

    bool dfs(int u) {
        for (int v : adj[u]) {
            int pu = pairV[v];
            if (pu == -1 || (dist[pu] == dist[u] + 1 && dfs(pu))) {
                pairU[u] = v;
                pairV[v] = u;
                return true;
            }
        }
        dist[u] = -1;
        return false;
    }

    int maxMatching() {
        int matching = 0;
        while (bfs()) {
            for (int u = 0; u < nL; ++u)
                if (pairU[u] == -1 && dfs(u))
                    ++matching;
        }
        return matching;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;
    int N = n * m;
    vector<int> grid(N);
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < m; ++j)
            cin >> grid[i * m + j];

    int maxId = 0;
    for (int x : grid) maxId = max(maxId, x);
    vector<pair<int,int>> pos1(maxId + 1, {-1, -1});
    vector<pair<int,int>> pos2(maxId + 1, {-1, -1});

    // record positions of each pair id
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            int id = grid[i * m + j];
            if (pos1[id].first == -1) pos1[id] = {i, j};
            else pos2[id] = {i, j};
        }
    }

    // map cells to bipartite indices
    vector<int> leftId(N, -1), rightId(N, -1);
    int nL = 0, nR = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            int idx = i * m + j;
            if ((i + j) % 2 == 0) leftId[idx] = nL++;
            else rightId[idx] = nR++;
        }
    }

    HopcroftKarp hk(nL, nR);

    // build edges for pairs whose two cells are opposite colors
    for (int id = 1; id <= maxId; ++id) {
        auto [i1, j1] = pos1[id];
        auto [i2, j2] = pos2[id];
        int idx1 = i1 * m + j1;
        int idx2 = i2 * m + j2;
        bool c1 = (i1 + j1) % 2 == 0;
        bool c2 = (i2 + j2) % 2 == 0;
        if (c1 == c2) continue; // same color, cannot be adjacent in final
        int u, v;
        if (c1) {
            u = leftId[idx1];
            v = rightId[idx2];
        } else {
            u = leftId[idx2];
            v = rightId[idx1];
        }
        hk.addEdge(u, v);
    }

    int maxMatch = hk.maxMatching();
    int answer = n * m - 2 * maxMatch;
    cout << answer << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;
    int N = n * m;
    vector<vector<int>> a(n, vector<int>(m));
    int maxId = 0;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < m; ++j) {
            cin >> a[i][j];
            maxId = max(maxId, a[i][j]);
        }

    // positions of each pair id: exactly two cells
    vector<pair<int,int>> p1(maxId+1, {-1,-1}), p2(maxId+1, {-1,-1});
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < m; ++j) {
            int id = a[i][j];
            if (p1[id].first == -1) p1[id] = {i,j};
            else p2[id] = {i,j};
        }

    int V = N;
    int S = V, T = V+1;
    int tot = T+1;

    struct Edge { int to, rev, cap, cost; };
    const int INF = 1e9;
    vector<vector<Edge>> g(tot);

    auto add_edge = [&](int u, int v, int cap, int cost) {
        Edge a{v, (int)g[v].size(), cap, cost};
        Edge b{u, (int)g[u].size(), 0, -cost};
        g[u].push_back(a);
        g[v].push_back(b);
    };

    auto id = [&](int i, int j){ return i*m + j; };

    // build graph
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < m; ++j) {
            int u = id(i,j);
            if ((i + j) % 2 == 0) {
                add_edge(S, u, 1, 0);
                static int di[4] = {1,-1,0,0};
                static int dj[4] = {0,0,1,-1};
                for (int k = 0; k < 4; ++k) {
                    int ni = i + di[k], nj = j + dj[k];
                    if (ni < 0 || ni >= n || nj < 0 || nj >= m) continue;
                    int v = id(ni,nj);
                    int cost = (a[i][j] == a[ni][nj]) ? 0 : 1;
                    add_edge(u, v, 1, cost);
                }
            } else {
                add_edge(u, T, 1, 0);
            }
        }

    // min-cost max-flow (successive SPFA / Bellman-Ford)
    int flow = 0, cost = 0;
    while (true) {
        vector<int> dist(tot, INF), inq(tot, 0), pv_v(tot, -1), pv_e(tot, -1);
        queue<int> q;
        dist[S] = 0;
        q.push(S);
        inq[S] = 1;
        while (!q.empty()) {
            int v = q.front(); q.pop();
            inq[v] = 0;
            for (int i = 0; i < (int)g[v].size(); ++i) {
                Edge &e = g[v][i];
                if (e.cap > 0 && dist[e.to] > dist[v] + e.cost) {
                    dist[e.to] = dist[v] + e.cost;
                    pv_v[e.to] = v;
                    pv_e[e.to] = i;
                    if (!inq[e.to]) {
                        inq[e.to] = 1;
                        q.push(e.to);
                    }
                }
            }
        }
        if (dist[T] == INF) break;
        int addf = INF;
        for (int v = T; v != S; v = pv_v[v]) {
            Edge &e = g[pv_v[v]][pv_e[v]];
            addf = min(addf, e.cap);
        }
        for (int v = T; v != S; v = pv_v[v]) {
            Edge &e = g[pv_v[v]][pv_e[v]];
            e.cap -= addf;
            g[v][e.rev].cap += addf;
        }
        flow += addf;
        cost += addf * dist[T];
    }

    cout << cost << '\n';
    return 0;
}
